
.cc-card {
  width: 100%;
  max-width: 680px;
  margin: 0 auto;
  background: var(--c-surface);
  border: 2px solid var(--c-border);
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 4px 16px rgba(43, 45, 66, 0.15);
  font-size: 14px;
}

.cc-header {
  padding: 16px 18px;
  background: linear-gradient(135deg, var(--c-primary) 0%, var(--c-primary-dark) 100%);
  color: #fff;
}

.cc-view {
  display: inline-block;
  background: rgba(255, 255, 255, 0.2);
  padding: 2px 10px;
  border-radius: 10px;
  font-size: 0.75rem;
  margin-bottom: 8px;
  i { margin-right: 4px; }
}

.cc-title {
  font-size: 1.25rem;
  font-weight: 800;
}

.cc-sub {
  font-size: 0.8rem;
  opacity: 0.9;
}

.cc-body {
  padding: 14px 18px 18px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.cc-step {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.step-title {
  font-size: 0.95rem;
  font-weight: 800;
  color: var(--c-primary-dark);
}

.step-no {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  background: var(--c-primary);
  color: #fff;
  border-radius: 50%;
  font-size: 0.75rem;
  margin-right: 6px;
}

.type-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 10px;
}

.type-card {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 12px;
  border: 2px solid var(--c-border);
  border-radius: 10px;
  background: var(--c-surface-alt);
  cursor: pointer;
  text-align: left;
  font-family: inherit;
  transition: all 0.2s;

  i { font-size: 1.2rem; color: var(--c-muted); }
  b { font-size: 0.95rem; color: var(--c-ink); }
  span { font-size: 0.72rem; color: var(--c-muted); }

  &:hover { border-color: var(--c-primary); }
  &.active {
    border-color: var(--c-primary);
    background: #e8f5ee;
    i { color: var(--c-primary); }
  }
}

.origin-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.origin-chip {
  padding: 5px 12px;
  border: 1.5px solid var(--c-border);
  border-radius: 16px;
  background: var(--c-surface-alt);
  font-size: 0.8rem;
  cursor: pointer;
  font-family: inherit;
  transition: all 0.15s;

  &:hover { border-color: var(--c-gold); }
  &.active {
    background: var(--c-gold);
    border-color: var(--c-gold);
    color: #fff;
    font-weight: 700;
  }
}

.origin-hint {
  font-size: 0.8rem;
  color: var(--c-muted);
  font-style: italic;
}

.origin-preview {
  border: 1.5px solid var(--c-border);
  border-radius: 10px;
  padding: 12px;
  background: var(--c-surface-alt);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.preview-head {
  display: flex;
  align-items: center;
  gap: 8px;
  strong { font-size: 1.05rem; }
}

.preview-tag {
  background: var(--c-primary);
  color: #fff;
  font-size: 0.68rem;
  padding: 2px 8px;
  border-radius: 10px;
}

.preview-desc {
  font-size: 0.8rem;
  color: var(--c-ink);
}

.preview-goal {
  font-size: 0.8rem;
  color: var(--c-gold);
  font-weight: 700;
  i { margin-right: 4px; }
}

.preview-stats {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.ps-cell {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: #fff;
  border: 1px solid var(--c-border);
  border-radius: 8px;
  padding: 4px 10px;
  b { font-size: 0.68rem; color: var(--c-muted); }
  em { font-style: normal; font-weight: 800; font-family: var(--font-num); font-size: 0.9rem; }
}

.preview-apt {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.pa-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  border: 1px solid var(--c-border);
  border-radius: 6px;
  padding: 2px 7px;
  background: #fff;
  font-size: 0.7rem;
  b { color: var(--c-muted); font-weight: 600; }
  em { font-style: normal; font-weight: 800; font-family: var(--font-num); color: var(--c-primary-dark); }
}

.preview-skills {
  font-size: 0.75rem;
  color: var(--c-muted);
  i { margin-right: 4px; color: var(--c-warning); }
  .sk {
    font-style: normal;
    background: #fff;
    border: 1px solid var(--c-border);
    border-radius: 6px;
    padding: 1px 7px;
    margin-right: 4px;
    &.unique {
      background: linear-gradient(135deg, #fff8e1, #ffe9b3);
      border-color: var(--c-warning);
      color: #8a6d00;
      font-weight: 700;
    }
  }
}

.custom-form {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field-label {
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--c-primary-dark);
  i { margin-right: 4px; }
}

.text-input {
  border: 1.5px solid var(--c-border);
  border-radius: 8px;
  padding: 8px 12px;
  font-size: 0.95rem;
  font-family: inherit;
  background: #fff;
  color: var(--c-ink);
  &:focus { outline: 2px solid var(--c-primary); border-color: transparent; }
}

.stat-slider {
  display: flex;
  align-items: center;
  gap: 10px;
}

.ss-name {
  width: 44px;
  font-size: 0.8rem;
  font-weight: 700;
}

.ss-range {
  flex: 1;
  accent-color: var(--c-primary);
}

.ss-value {
  width: 44px;
  text-align: right;
  font-family: var(--font-num);
  font-weight: 700;
  font-size: 0.85rem;
}

.apt-group {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-bottom: 6px;
}

.ag-name {
  width: 44px;
  font-size: 0.78rem;
  font-weight: 800;
  color: var(--c-muted);
  padding-top: 3px;
}

.ag-items {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  flex: 1;
}

.ag-item {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  border: 1px solid var(--c-border);
  border-radius: 6px;
  padding: 3px 6px;
  background: #fff;
  b { font-size: 0.7rem; color: var(--c-muted); }
}

.apt-select {
  border: none;
  background: var(--c-surface-alt);
  font-family: var(--font-num);
  font-weight: 800;
  color: var(--c-primary-dark);
  font-size: 0.8rem;
  padding: 1px 2px;
  border-radius: 4px;
  cursor: pointer;
}

.confirm-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 20px;
  border: none;
  border-radius: 10px;
  background: linear-gradient(135deg, var(--c-primary), var(--c-primary-dark));
  color: #fff;
  font-size: 1rem;
  font-weight: 800;
  font-family: inherit;
  cursor: pointer;
  transition: all 0.2s;
  box-shadow: 0 3px 10px rgba(46, 139, 87, 0.3);

  &:hover:not(:disabled) { filter: brightness(1.08); transform: translateY(-1px); }
  &:active:not(:disabled) { transform: translateY(0); }
  &:disabled { opacity: 0.5; cursor: not-allowed; }
}

.cc-done {
  padding: 30px 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  text-align: center;
}

.done-check {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--c-primary);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
}

.cc-done h3 {
  font-size: 1.2rem;
  color: var(--c-primary-dark);
}

.done-summary {
  width: 100%;
  max-width: 420px;
  border: 1.5px solid var(--c-border);
  border-radius: 10px;
  padding: 12px 16px;
  background: var(--c-surface-alt);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.done-row {
  display: flex;
  justify-content: space-between;
  font-size: 0.85rem;
  span { color: var(--c-muted); }
  strong { color: var(--c-ink); font-family: var(--font-num); }
}

.done-tip {
  font-size: 0.8rem;
  color: var(--c-muted);
  i { color: var(--c-warning); margin-right: 4px; }
}

.narrative-box {
  width: 100%;
  max-width: 440px;
  border: 1.5px solid var(--c-border);
  border-radius: 10px;
  background: var(--c-surface-alt);
  padding: 10px 14px;
  text-align: left;
}

.narrative-head {
  font-size: 0.78rem;
  font-weight: 800;
  color: var(--c-primary-dark);
  margin-bottom: 6px;
  i { margin-right: 4px; }
}

.narrative-text {
  font-size: 0.82rem;
  color: var(--c-ink);
  line-height: 1.7;
  white-space: pre-wrap;
  max-height: 220px;
  overflow-y: auto;
}

.sent-tip {
  font-size: 0.85rem;
  color: var(--c-primary-dark);
  font-weight: 700;
  i { margin-right: 5px; }
}

@media (max-width: 560px) {
  .type-grid { grid-template-columns: 1fr; }
  .stat-slider { flex-wrap: wrap; }
}
